"""Core trimming heuristics for messy CSV files."""

from __future__ import annotations

import math
import re
from typing import Any, Callable, Optional, Tuple

import numpy as np
import pandas as pd

from csv_trimming.logger import logger


SPACES = [" ", "\t", "\n", "\r", "\x0b", "\x0c"]
UNICODE_SPACES = [
    "\u00a0",
    "\u1680",
    "\u180e",
    "\u2000",
    "\u2001",
    "\u2002",
    "\u2003",
    "\u2004",
    "\u2005",
    "\u2006",
    "\u2007",
    "\u2008",
    "\u2009",
    "\u200a",
    "\u2028",
    "\u2029",
    "\u202f",
    "\u205f",
    "\u3000",
    "\ufeff",
    "\u200b",
]
SPACE_LIKE = sorted(SPACES + UNICODE_SPACES, key=lambda x: -len(x))

NAN_LIKE_ARTIFACTS = [
    "",
    "-",
    "--",
    "---",
    ".",
    "..",
    "...",
    "n/a",
    "na",
    "nan",
    "null",
    "none",
    "nil",
    "missing",
    "not available",
    "not applicable",
]
UNICODE_NAN_LIKE_ARTIFACTS = [
    "n.a.",
    "n/d",
    "n\\a",
    "sconosciuto",
    "nd",
    "n.d.",
    "non disponible",
]
NAN_LIKE = NAN_LIKE_ARTIFACTS + UNICODE_NAN_LIKE_ARTIFACTS

DEFAULT_HEADER_PATTERN = re.compile(r"^(unnamed:\s*\d+|column\s*#?\d+)$", re.IGNORECASE)
NUMERIC_PATTERN = re.compile(r"^[+-]?(?:\d+(?:\.\d+)?|\.\d+)$")


def _is_scalar_nan(candidate: Any) -> bool:
    """Return True if the candidate is a scalar NaN/NA value."""

    try:
        return bool(pd.isna(candidate))
    except TypeError:
        return False


def _normalize_string(candidate: str) -> str:
    """Return normalized string with space-like artifacts collapsed."""

    normalized = candidate
    for artifact in SPACE_LIKE:
        normalized = normalized.replace(artifact, " ")
    normalized = re.sub(r"\s+", " ", normalized)
    return normalized.strip()


def is_nan(candidate: Any) -> bool:
    """Return True if the given candidate is NaN-like."""

    if candidate is None:
        return True
    if isinstance(candidate, (float, np.floating)) and math.isnan(candidate):
        return True
    if candidate is pd.NA:
        return True
    if _is_scalar_nan(candidate):
        return True
    if isinstance(candidate, str):
        normalized = _normalize_string(candidate).casefold()
        return normalized in {token.casefold() for token in NAN_LIKE}
    return False


def _standardize_header_value(value: Any, position: int) -> str:
    """Return a human-friendly header name."""

    if is_nan(value):
        return f"column #{position + 1}"
    if isinstance(value, str):
        cleaned = _normalize_string(value)
    else:
        cleaned = _normalize_string(str(value))
    if not cleaned:
        return f"column #{position + 1}"
    return cleaned


def _score_header_candidates(values: list[Any]) -> float:
    """Return heuristic score for candidate header values."""

    standardized = [_standardize_header_value(value, index) for index, value in enumerate(values)]
    non_empty = sum(not DEFAULT_HEADER_PATTERN.match(name) for name in standardized)
    unique = len({name.casefold() for name in standardized})
    alpha_like = sum(any(character.isalpha() for character in name) for name in standardized)
    numeric_like = sum(bool(NUMERIC_PATTERN.fullmatch(name)) for name in standardized)
    return float(non_empty * 2 + unique + alpha_like - numeric_like)


class CSVTrimmer:
    """Class handling the cleaning up of malformed CSVs using heuristics."""

    def __init__(
        self,
        correlation_callback: Optional[
            Callable[[pd.Series, pd.Series], Tuple[bool, pd.Series]]
        ] = None,
    ):
        """Create new CSVTrimmer object."""

        self._correlation_callback = correlation_callback

    def _mask_edges(self, mask: np.ndarray) -> np.ndarray:
        """Return boolean array with only True values attached to the sides."""

        flat = np.asarray(mask, dtype=bool).reshape(-1)
        if flat.size == 0:
            return flat
        result = np.zeros_like(flat, dtype=bool)

        left = 0
        while left < flat.size and flat[left]:
            result[left] = True
            left += 1

        right = flat.size - 1
        while right >= 0 and flat[right]:
            result[right] = True
            right -= 1

        return result.reshape(np.asarray(mask).shape)

    def _cell_is_meaningful(self, value: Any) -> bool:
        """Return whether the value contains meaningful content."""

        return not is_nan(value)

    def trim_padding(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return given CSV with trimmed rows and columns."""

        if csv.empty:
            return csv.copy()

        logger.info("Trimming padding")
        meaningful = csv.applymap(self._cell_is_meaningful)
        row_has_values = meaningful.any(axis=1).to_numpy(dtype=bool)
        col_has_values = meaningful.any(axis=0).to_numpy(dtype=bool)

        if not row_has_values.any() or not col_has_values.any():
            return csv.iloc[0:0, 0:0].copy()

        top = int(np.argmax(row_has_values))
        bottom = len(row_has_values) - int(np.argmax(row_has_values[::-1]))
        left = int(np.argmax(col_has_values))
        right = len(col_has_values) - int(np.argmax(col_has_values[::-1]))
        return csv.iloc[top:bottom, left:right].copy()

    def _header_is_reliable(self, columns: pd.Index) -> bool:
        """Return whether the existing columns look like a deliberate header."""

        values = list(columns)
        if not values:
            return False

        standardized = [_standardize_header_value(value, index) for index, value in enumerate(values)]
        non_default = sum(not DEFAULT_HEADER_PATTERN.match(name) for name in standardized)
        alpha_like = sum(any(character.isalpha() for character in name) for name in standardized)
        unique = len({name.casefold() for name in standardized})
        return non_default >= max(1, len(values) // 2) and alpha_like >= 1 and unique >= max(1, len(values) // 2)

    def _pick_header_row(self, csv: pd.DataFrame) -> int:
        """Return the index position of the row that most likely contains a header."""

        candidate_limit = min(len(csv), 10)
        best_position = 0
        best_score = float("-inf")
        for position in range(candidate_limit):
            row = csv.iloc[position].tolist()
            row_score = _score_header_candidates(row) - position * 0.25
            if row_score > best_score:
                best_score = row_score
                best_position = position
        return best_position

    def restore_header(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return CSV with restored first row as header of CSV."""

        if csv.empty:
            return csv.copy()

        logger.info("Restoring header")
        working = csv.copy()

        existing_header_score = _score_header_candidates(list(working.columns))
        header_row_position = self._pick_header_row(working)
        candidate_score = _score_header_candidates(working.iloc[header_row_position].tolist())

        if self._header_is_reliable(working.columns) and existing_header_score >= candidate_score:
            raw_header = list(working.columns)
            body = working.copy()
        else:
            raw_header = working.iloc[header_row_position].tolist()
            body = working.iloc[header_row_position + 1 :].copy()

        header: list[str] = []
        counts: dict[str, int] = {}
        for position, value in enumerate(raw_header):
            candidate = _standardize_header_value(value, position)
            seen = counts.get(candidate.casefold(), 0)
            if seen == 0:
                resolved = candidate
            elif seen == 1:
                resolved = f"{candidate}.duplicated"
            else:
                resolved = f"{candidate}.duplicated.{seen}"
            counts[candidate.casefold()] = seen + 1
            header.append(resolved)

        body.columns = header
        body.columns.name = None
        return body.reset_index(drop=True)

    def drop_empty_columns(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return DataFrame with removed empty columns."""

        if csv.empty:
            return csv.copy()

        logger.info("Dropping empty columns")
        keep_mask = [not csv.iloc[:, index].map(is_nan).all() for index in range(csv.shape[1])]
        if not any(keep_mask):
            return csv.iloc[:, 0:0].copy()
        return csv.loc[:, keep_mask].copy()

    def drop_duplicated_schema(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return DataFrame with removed duplicated schema rows."""

        if csv.empty:
            return csv.copy()

        logger.info("Dropping duplicated schema rows")
        header = [_normalize_string(str(column)).casefold() for column in csv.columns]
        if not header:
            return csv.copy()

        duplicated_rows = []
        for index, row in csv.iterrows():
            normalized_row = [
                "" if is_nan(value) else _normalize_string(str(value)).casefold()
                for value in row.tolist()
            ]
            duplicated_rows.append(normalized_row == header)

        if not any(duplicated_rows):
            return csv.copy()
        return csv.loc[[not duplicated for duplicated in duplicated_rows]].copy()

    def drop_empty_rows(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return DataFrame with removed empty rows."""

        if csv.empty:
            return csv.copy()

        logger.info("Dropping empty rows")
        keep_mask = [not csv.iloc[index, :].map(is_nan).all() for index in range(csv.shape[0])]
        if not any(keep_mask):
            return csv.iloc[0:0].copy()
        return csv.loc[keep_mask].copy()

    def _deep_strip(self, string: str) -> str:
        """Return string without continuous spaces."""

        return _normalize_string(string)

    def trim_spaces(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return dataframe without multiple spaces."""

        logger.info("Trimming spaces")
        working = csv.copy()
        working.columns = [
            self._deep_strip(column) if isinstance(column, str) else column for column in working.columns
        ]

        def _strip_cell(value: Any) -> Any:
            if isinstance(value, str):
                return self._deep_strip(value)
            return value

        return working.apply(lambda column: column.map(_strip_cell))

    def restore_true_nan(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return CSV with restored True NaN values."""

        logger.info("Restoring NaN-like values")
        working = csv.copy()

        def _restore(value: Any) -> Any:
            if is_nan(value):
                return np.nan
            return value

        return working.apply(lambda column: column.map(_restore))

    def normalize_correlated_rows(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return normalized correlated rows."""

        if self._correlation_callback is None or csv.empty:
            return csv.copy()

        logger.info("Normalizing correlated rows")
        rows: list[pd.Series] = []
        position = 0
        while position < len(csv):
            current_row = csv.iloc[position].copy()
            skip_next = False
            if position + 1 < len(csv):
                next_row = csv.iloc[position + 1].copy()
                skip_next, current_row = self._correlation_callback(current_row, next_row)
            rows.append(current_row)
            position += 2 if skip_next else 1

        if not rows:
            return csv.iloc[0:0].copy()

        normalized = pd.DataFrame(rows)
        normalized = normalized.reindex(columns=list(dict.fromkeys(list(normalized.columns))), copy=False)
        return normalized.reset_index(drop=True)

    def trim(
        self,
        csv: pd.DataFrame,
        restore_header: bool = True,
        drop_padding: bool = True,
        drop_duplicated_schema: bool = True,
    ) -> pd.DataFrame:
        """Return sanitized version of given dataframe."""

        if not isinstance(csv, pd.DataFrame):
            raise TypeError("csv must be a pandas.DataFrame")

        logger.info("Starting trim pipeline")
        cleaned = csv.copy()
        cleaned = self.trim_spaces(cleaned)
        if drop_padding:
            cleaned = self.trim_padding(cleaned)
        cleaned = self.drop_empty_rows(cleaned)
        if restore_header:
            cleaned = self.restore_header(cleaned)
        cleaned = self.restore_true_nan(cleaned)
        cleaned = self.normalize_correlated_rows(cleaned)
        cleaned = self.drop_empty_columns(cleaned)
        if drop_duplicated_schema:
            cleaned = self.drop_duplicated_schema(cleaned)
        cleaned = self.drop_empty_rows(cleaned)
        cleaned = cleaned.reset_index(drop=True)
        cleaned.index.name = None
        cleaned.columns.name = None
        return cleaned


def trim(
    csv: pd.DataFrame,
    restore_header: bool = True,
    drop_padding: bool = True,
    drop_duplicated_schema: bool = True,
    correlation_callback: Optional[
        Callable[[pd.Series, pd.Series], Tuple[bool, pd.Series]]
    ] = None,
) -> pd.DataFrame:
    """Trim the given dataframe using a fresh trimmer instance."""

    return CSVTrimmer(correlation_callback=correlation_callback).trim(
        csv,
        restore_header=restore_header,
        drop_padding=drop_padding,
        drop_duplicated_schema=drop_duplicated_schema,
    )

