from __future__ import annotations

import numpy as np
import pandas as pd

from csv_trimming import CSVTrimmer


def correlation_callback(current_row: pd.Series, next_row: pd.Series):
    if (
        pd.isna(current_row["surname"])
        and pd.isna(next_row["name"])
        and pd.notna(next_row["surname"])
    ):
        merged = current_row.copy()
        merged["surname"] = next_row["surname"]
        if "note" in next_row and pd.notna(next_row["note"]):
            merged["note"] = next_row["note"]
        return True, merged
    return False, current_row


def test_normalize_correlated_rows_merges_callback_matches() -> None:
    csv = pd.DataFrame(
        {
            "name": ["Alice", np.nan, "Bob"],
            "surname": [np.nan, "Smith", np.nan],
            "age": ["30", np.nan, "41"],
            "note": [np.nan, "carried", np.nan],
        }
    )
    result = CSVTrimmer(correlation_callback=correlation_callback).trim(
        csv,
        restore_header=False,
        drop_padding=False,
        drop_duplicated_schema=False,
    )
    expected = pd.DataFrame(
        {
            "name": ["Alice", "Bob"],
            "surname": ["Smith", np.nan],
            "age": ["30", "41"],
            "note": ["carried", np.nan],
        }
    )
    assert result.equals(expected)
